#!/usr/bin/env python3
"""Local, side-effect-free stock reconciliation with a file CLI adapter."""

import json
import sys


RECEIPT_KEYS = {
    "case_id",
    "status",
    "on_hand",
    "available",
    "issue",
    "action_performed",
}
EVENT_KEYS = {"id", "type", "sku", "quantity"}
EVENT_TYPES = {"receipt", "ship", "reserve"}


def _receipt(case_id, status, issue, on_hand=None, available=None):
    return {
        "case_id": case_id if isinstance(case_id, str) else "",
        "status": status,
        "on_hand": {} if on_hand is None else on_hand,
        "available": {} if available is None else available,
        "issue": issue,
        "action_performed": False,
    }


def _is_quantity(value):
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def reconcile_batch(batch):
    """Return one desk receipt for a decoded JSON batch; mutate nothing."""
    if not isinstance(batch, dict):
        return _receipt("", "needs_review", "invalid")

    case_id = batch.get("case_id", "")
    if "case_id" not in batch or "opening" not in batch or "events" not in batch:
        return _receipt(case_id, "needs_input", "missing")
    if not isinstance(case_id, str) or not case_id:
        return _receipt(case_id, "needs_review", "invalid")

    opening = batch["opening"]
    events = batch["events"]
    if not isinstance(opening, dict) or not isinstance(events, list):
        return _receipt(case_id, "needs_review", "invalid")
    if any(not isinstance(sku, str) or not sku or not _is_quantity(qty)
           for sku, qty in opening.items()):
        return _receipt(case_id, "needs_review", "invalid")

    unique = {}
    invalid = False
    conflict = False
    for event in events:
        if not isinstance(event, dict) or set(event) != EVENT_KEYS:
            invalid = True
            continue
        event_id = event["id"]
        sku = event["sku"]
        event_type = event["type"]
        quantity = event["quantity"]
        if (not isinstance(event_id, str) or not event_id
                or not isinstance(sku, str) or not sku
                or not isinstance(event_type, str)
                or event_type not in EVENT_TYPES
                or not _is_quantity(quantity)
                or sku not in opening):
            invalid = True
            continue

        content = (event_id, event_type, sku, quantity)
        prior = unique.get(event_id)
        if prior is None:
            unique[event_id] = content
        elif prior != content:
            conflict = True

    if conflict:
        return _receipt(case_id, "needs_review", "conflict")
    if invalid:
        return _receipt(case_id, "needs_review", "invalid")

    on_hand = dict(opening)
    reserved = {sku: 0 for sku in opening}
    for _, event_type, sku, quantity in unique.values():
        if event_type == "receipt":
            on_hand[sku] += quantity
        elif event_type == "ship":
            on_hand[sku] -= quantity
        else:
            reserved[sku] += quantity

    available = {sku: on_hand[sku] - reserved[sku] for sku in opening}
    if any(value < 0 for value in on_hand.values()) or any(
            value < 0 for value in available.values()):
        return _receipt(case_id, "needs_review", "negative")
    return _receipt(case_id, "completed", "none", on_hand, available)


def main(argv=None):
    argv = sys.argv if argv is None else argv
    if len(argv) != 3:
        return 2
    input_path, output_path = argv[1], argv[2]
    try:
        with open(input_path, "r", encoding="utf-8") as source:
            batch = json.load(source)
        receipt = reconcile_batch(batch)
    except (OSError, UnicodeError, json.JSONDecodeError):
        receipt = _receipt("", "failed", "failed")
    except Exception:
        receipt = _receipt("", "failed", "failed")

    try:
        with open(output_path, "w", encoding="utf-8") as target:
            json.dump(receipt, target, ensure_ascii=False, separators=(",", ":"))
            target.write("\n")
    except (OSError, UnicodeError):
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

