import copy
import json
import unittest

from reconcile import RECEIPT_KEYS, reconcile_batch


class ReconcileTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        with open("dev_inputs.json", encoding="utf-8") as source:
            cls.examples = json.load(source)

    def assert_contract(self, receipt):
        self.assertEqual(set(receipt), RECEIPT_KEYS)
        self.assertIs(receipt["action_performed"], False)

    def test_supplied_examples(self):
        good, conflict = map(reconcile_batch, self.examples)
        self.assertEqual(good, {
            "case_id": "s-dev-good", "status": "completed",
            "on_hand": {"sensor": 8}, "available": {"sensor": 6},
            "issue": "none", "action_performed": False,
        })
        self.assertEqual(conflict["status"], "needs_review")
        self.assertEqual(conflict["issue"], "conflict")
        self.assertEqual(conflict["on_hand"], {})
        self.assertEqual(conflict["available"], {})

    def test_duplicate_counts_once_and_reservation_is_not_shipment(self):
        event = {"id": "r", "type": "reserve", "sku": "x", "quantity": 2}
        batch = {"case_id": "dup", "opening": {"x": 5},
                 "events": [event, dict(event)]}
        before = copy.deepcopy(batch)
        result = reconcile_batch(batch)
        self.assertEqual(result["on_hand"], {"x": 5})
        self.assertEqual(result["available"], {"x": 3})
        self.assertEqual(batch, before)

    def test_invalid_and_negative_publish_no_quantities(self):
        cases = [
            ({"case_id": "unknown", "opening": {"x": 1}, "events": [
                {"id": "1", "type": "ship", "sku": "y", "quantity": 1}
            ]}, "invalid"),
            ({"case_id": "bool", "opening": {"x": True}, "events": []},
             "invalid"),
            ({"case_id": "bad-type", "opening": {"x": 1}, "events": [
                {"id": "1", "type": [], "sku": "x", "quantity": 1}
            ]}, "invalid"),
            ({"case_id": "negative", "opening": {"x": 1}, "events": [
                {"id": "1", "type": "reserve", "sku": "x", "quantity": 2}
            ]}, "negative"),
        ]
        for batch, issue in cases:
            with self.subTest(issue=issue):
                result = reconcile_batch(batch)
                self.assert_contract(result)
                self.assertEqual(result["issue"], issue)
                self.assertEqual((result["on_hand"], result["available"]), ({}, {}))

    def test_missing_fields_need_input(self):
        result = reconcile_batch({"case_id": "missing", "opening": {}})
        self.assertEqual(result["status"], "needs_input")
        self.assertEqual(result["issue"], "missing")
        self.assert_contract(result)


if __name__ == "__main__":
    unittest.main()
